{"command":"$dir='C:\Users\24228\.codex\rules'; if (!(Test-Path $dir)) { throw "Directory not found: $dir" }
Get-ChildItem -Path $dir -Filter *.rules -File | ForEach-Object {
  $bytes=[System.IO.File]::ReadAllBytes($_.FullName)
  $hasBom=$bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF
  [PSCustomObject]@{ File=$_.FullName; HasUtf8Bom=$hasBom; Size=$bytes.Length }
} | Format-Table -AutoSize"}
